v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(make_indent(depth.clone()), "for {
".to_string()), inner.clone()), "
".to_string()), make_indent(depth.clone())), "}".to_string())
